/**
 * Devī Māhātmya (Durgā Saptaśatī, Mārkaṇḍeya Purāṇa) for pārāyaṇa: Devī Kavaca, Argalā and
 * Kīlaka (order 1–3), the 13 chapters (order 4–16, 700 mantras), then the Ṛgvedic Rātri Sūkta
 * (recited before chapter 1), Devī Sūkta (after chapter 13) and the Devyaparādha-kṣamāpana
 * Stotra (order 17–19). Generated from the collated data described below.
 *
 * SOURCES (only the Sanskrit was taken; the texts are ancient and public domain, and every
 * summary and meaning here is original):
 * - Base: github.com/vishvAsa/purANam (branch content), mArkaNDeya-purANam/durgA-saptashatI:
 *   the मूलम् of the Gita Press Durgā Saptaśatī, typed with the Gita Press verse ends (॥).
 * - Witness F: Peter Freund's typed Durgā Saptaśatī, github.com/sanskrit/raw_etexts,
 *   kAvyam/padyam/peterFreund/stotram/durga_saptashati.md (Gita Press numbering, no colophon
 *   text, some legacy-font breaks).
 * - Witness K: github.com/kaustubhk24/sangrah, docs/pothi/durga-saptshati-sanskrit (13
 *   chapters), docs/stotras-shlok (Argalā, Kīlaka, Aparādha), docs/Sukt/devi-suktam.md.
 * - Spot checks: L. Poley, Devīmāhātmyam (1831), typed in sanskrit/raw_etexts (ebhAratI);
 *   Sanskrit Wikisource चण्डीकवचम्, अर्गलास्तोत्रम्, कीलकस्तोत्रम्, देव्यपराधक्षमापनस्तोत्रम्
 *   (copies in github.com/con-jo-ry/ilx_skt); pulkban.github.io Devī Kavaca; Ṛgveda 10.125 and
 *   10.127 (github.com/vishvAsa/vedAH_Rk).
 *
 * NUMBERING follows the Gita Press 700: every speaker line (… उवाच) has its own number, and
 * Gita Press numbers some half-verses on their own, so the pairing of half-lines into numbered
 * mantras shifts inside chapters 1, 4, 8, 10, 11, 12 and 13 (a mantra may be ½ or 1½ ślokas).
 * In chapter 5 each “yā devī sarvabhūteṣu” stanza counts three (one per नमस्तस्यै: the 66
 * avadāna mantras); it is stored once with n = the last of the three, so the validator reports
 * those jumps on purpose. Chapters: 104, 69, 44, 42, 129, 24, 27, 63, 41, 32, 55, 41, 29.
 * Uvāca 57 + half-verses 42 + ślokas 535 + avadāna 66 = 700, and each chapter's counts match
 * the statistics in its Gita Press colophon. Units were cut at the base's ॥ marks and checked
 * number by number against F's explicit numbers; F differs only at 10.32 (missing), 13.27–29
 * (divided differently) and 2.63 (no bracketed line). The bīja syllables Gita Press prints at
 * the carita boundaries (ॐ ऐं / ह्रीं / क्लीं …) are described in a note, not put in the text.
 *
 * COLLATION: every numbered unit was compared word by word with F and K, and
 * scripts/collate.ts was run against each witness. Changes to the base:
 * - 1.5 pāda layout restored; 1.27 भवाल्ँ लुब्धैः → भवाँल्लुब्धैः (sandhi)
 * - 1.13 शूरो हस्ती → शूरहस्ती (K, Poley; F has शूरो हस्ती)
 * - 1.77 सिंहृति → संहृति, महास्मृतः → महास्मृतिः (F, K)
 * - 1.82: the base repeats यच्च किंचित्…; the duplicate was dropped (F, K numbering)
 * - 3.18 वाष्कलं → बाष्कलं (F, K, and the base itself at 2.42)
 * - 9.15 देव्या(स्) → देव्यास्; 10.24 उत्पात्य (उत्पाट्य) → उत्पाट्य
 * - 11.27 देविपापेभ्योऽनः → देवि पापेभ्यो नः (F, Poley, grammar; K has the base reading)
 * Where the base gives two readings, the first (the Gita Press one, matching its Hindi
 * translation) was kept by majority: 5.84 स्तवादियुक्तानां (K, Poley; F स्तवाभि°),
 * 12.6 शत्रुतो (K, Poley; F शत्रुभ्यो), 12.10 ममैतच्चरितम् (K; F ममैतन्माहात्म्यम्),
 * 13.11 यताहारौ (Poley; F यतात्मानौ), 13.23 सावर्णिको नाम मनुर्भवान् (K; F मनुर्नाम भवान्),
 * 1.13 (see above). Kept against one witness, e.g. 1.69 एकाग्रहृदयस्थितः, 4.10 वार्ता,
 * 5.77 व्याप्तिदेव्यै, 11.47 यन्मुनीन्, 12.41 पुष्पैर्धूपगन्धादिभिः; 11.10 सर्वमङ्गलमङ्गल्ये
 * (base, Poley) against सर्वमङ्गलमाङ्गल्ये (F, K). The lines Gita Press prints in brackets are
 * kept in brackets: 2.63 (कबन्धा युयुधुर्देव्या…) and 10.18 (अश्वांश्च पातयामास…); 10.32 is
 * counted in the 700, so its brackets were dropped.
 *
 * METRE: every anuṣṭubh half-verse has 16 syllables except 1.92 मधुकैटभौ दुरात्मानौ… and
 * 2.2 महिषेऽसुराणामधिपे… (17, the same in all witnesses). Vasantatilakā (4.2–23, 11.34) has 14
 * per pāda, upajāti (11.2–6, 29–33) 11, vaṃśastha (5.81–82) 12.
 *
 * AṄGAS: Kavaca 56, Argalā 25 and Kīlaka 14 verses as in Gita Press. F, Wikisource and pulkban
 * carry another recension of the Kavaca (about 50 verses, differently ordered) and of some
 * Argalā lines (12 देहि देवि परं सुखम्, 16 च मां कुरु); the Gita Press base is kept and its
 * Hindi translation confirms it. Kavaca ब्रह्माणि / इन्द्राणि (short i, needed by the metre) are
 * kept although the witnesses write ब्रह्माणी. The two pāṭha-krama verses after the Kīlaka
 * colophon in the base are left out.
 * EXTRAS: Rātri Sūkta 2 अमर्त्यानिवतो → अमर्त्या निवतो (F, Ṛgveda); Devī Sūkta 3 भूर्य्या° →
 * भूर्या°, 5 ब्राह्मणं → ब्रह्माणं (F, K, Ṛgveda), 8 दिवापर → दिवा पर. Vedic accents omitted.
 * Aparādha-kṣamāpana: base kept where Wikisource agrees against K (5 विविधविध°, 9 रुक्ष°,
 * 11 अपराधपरम्परापरं).
 *
 * NOT INCLUDED: the Saptaśatī nyāsas, Navārṇa vidhi, the three Rahasyas, Kṣamā-prārthanā and
 * Siddha-kuñjikā. The Tantrokta Rātri and Devī Sūktas are already here, within 1.70–87 and 5.9–82.
 * MEANINGS (original, en + kn): Argalā, the Nārāyaṇī stuti (11.2–35), both Vedic sūktas and the
 * Aparādha stotra; the chapters have chapter summaries only.
 */
