  summaryKn: 'ಇತರರ ಬಲವನ್ನು ಆಶ್ರಯಿಸಿದ್ದಾಳೆ ಎಂದು ಶುಂಭನು ದೇವಿಯನ್ನು ಹೀಯಾಳಿಸುತ್ತಾನೆ. "ಈ ಜಗತ್ತಿನಲ್ಲಿ ನಾನೊಬ್ಬಳೇ ಇದ್ದೇನೆ, ನನ್ನ ಹೊರತು ಬೇರೆ ಯಾರಿದ್ದಾರೆ?" ಎಂದು ದೇವಿಯು ಎಲ್ಲ ಮಾತೃಕೆಯರನ್ನೂ ತನ್ನಲ್ಲಿ ಲೀನಗೊಳಿಸುತ್ತಾಳೆ. ನೆಲದಲ್ಲೂ ಆಕಾಶದಲ್ಲೂ ನಡೆದ ದೀರ್ಘ ಯುದ್ಧದ ಬಳಿಕ ತ್ರಿಶೂಲದಿಂದ ಶುಂಭನನ್ನು ಸಂಹರಿಸುತ್ತಾಳೆ. ಜಗತ್ತು ಶಾಂತವಾಗುತ್ತದೆ; ದೇವತೆಗಳು ಆನಂದಿಸುತ್ತಾರೆ.',
