      noteKn: 'ಕೀಲಕದ ನಂತರ, ಮೊದಲ ಅಧ್ಯಾಯಕ್ಕೆ ಮೊದಲು ಪಠಿಸಿ. ವೈದಿಕ ಸ್ವರಚಿಹ್ನೆಗಳನ್ನು ಬಿಡಲಾಗಿದೆ.',
